    {
    "authkey": "",
    "token": {
      "token": {
      "token": {
        "permission": "rwx",
        "expires": "1571226882",
        "owner": "root",
        "group": "root",
        "generation": "0",
        "path": "/eos/dev/xrootd",
        "allowtree": false,
        "vtoken": "",
        "origins": []
      },
      "signature": "",
      "serialized": "",
      "seed": 0
      }
    }
    }

    reply:
